window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e4da0f9fa558a2d5"]={"versions": [{"id": "FIG-e4da0f9fa558a2d5", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt im Kontext des AUTOSAR-Modellaustauschs und der Werkzeug-Interoperabilität (AUTOSAR_TR_InteroperabilityOfAutosarTools). Das Diagramm veranschaulicht das Konzept der Modifikationserkennung (Modification Detection) bei der Modellzerlegung bzw. -zusammenführung über Teilmodelle (Partial Models) hinweg, speziell für Metaklassen, die über die Stereotyp-Annotation «atpSplitable» aggregiert sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert einen Begrenzungsrahmen mit der Bezeichnung „Lower partial model“, der zwei Metaklassen umfasst:</p>\n<ul class=\"fig-list\"><li><code>A</code>: Eine Metaklasse mit der Kennzeichnung bzw. Spezialisierung/Stereotyp <code>Identifiable</code>, dargestellt als farblich hervorgehobener (gelber/goldener) Block auf der aggregierenden Seite.\n</li><li><code>C</code>: Eine Metaklasse mit der Kennzeichnung <code>Identifiable</code>, dargestellt als heller Block auf der aggregierten Seite.\n</li><li>Beziehung: Eine gerichtete Komposition bzw. Aggregation (ausgefüllte schwarze Raute an Metaklasse <code>A</code>), die mit dem Stereotyp <code>«atpSplitable»</code> annotiert ist und Metaklasse <code>C</code> in <code>A</code> einbindet. Beide Metaklassen weisen ein leeres Attributfach auf.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktions- oder Sequenzabläufe. Die modellierte Beziehung definiert die strukturelle Aufteilbarkeit (Splitability): Da die Aggregation von <code>C</code> durch <code>A</code> mit <code>«atpSplitable»</code> markiert ist und beide Klassen <code>Identifiable</code> sind, können Instanzen von <code>C</code> innerhalb eines unteren Teilmodells („Lower partial model“) separat verteilt, instanziiert oder persistiert werden, ohne dass die übergeordnete Identität oder Eindeutigkeit der Aggregationshierarchie gebrochen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwicklungs- und werkzeugrelevante Vorgabe für AUTOSAR-Authoring- und Modellaustauschwerkzeuge:</p>\n<ul class=\"fig-list\"><li>Wenn eine Kompositionsbeziehung zwischen <code>Identifiable</code>-Elementen mit <code>«atpSplitable»</code> versehen ist, müssen Werkzeuge bei der Modellverarbeitung (Diffing, Merging, Export von Partial Models) berücksichtigen, dass Elemente vom Typ <code>C</code> in unterschiedlichen ARXML-Dateien bzw. Teilmodellen vorliegen können.\n</li><li>Für die Modifikations- und Konflikterkennung bedeutet dies, dass das Vorhandensein oder Fehlen von Elementen des Typs <code>C</code> in einem Teilmodell nicht zwingend als Löschung im Gesamtmodell interpretiert werden darf, sondern als splitbare Aggregation gemäß den AUTOSAR-Metamodellregeln aufgelöst werden muss.\n</li></ul>"}, {"id": "FIG-bea43565ecfe70ff", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt im Kontext des AUTOSAR-Modellaustauschs und der Werkzeug-Interoperabilität (AUTOSAR_TR_InteroperabilityOfAutosarTools). Das Diagramm veranschaulicht das Konzept der Modifikationserkennung (Modification Detection) bei der Modellzerlegung bzw. -zusammenführung über Teilmodelle (Partial Models) hinweg, speziell für Metaklassen, die über die Stereotyp-Annotation «atpSplitable» aggregiert sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert einen Begrenzungsrahmen mit der Bezeichnung „Lower partial model“, der zwei Metaklassen umfasst:</p>\n<ul class=\"fig-list\"><li><code>A</code>: Eine Metaklasse mit der Kennzeichnung bzw. Spezialisierung/Stereotyp <code>Identifiable</code>, dargestellt als farblich hervorgehobener (gelber/goldener) Block auf der aggregierenden Seite.\n</li><li><code>C</code>: Eine Metaklasse mit der Kennzeichnung <code>Identifiable</code>, dargestellt als heller Block auf der aggregierten Seite.\n</li><li>Beziehung: Eine gerichtete Komposition bzw. Aggregation (ausgefüllte schwarze Raute an Metaklasse <code>A</code>), die mit dem Stereotyp <code>«atpSplitable»</code> annotiert ist und Metaklasse <code>C</code> in <code>A</code> einbindet. Beide Metaklassen weisen ein leeres Attributfach auf.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktions- oder Sequenzabläufe. Die modellierte Beziehung definiert die strukturelle Aufteilbarkeit (Splitability): Da die Aggregation von <code>C</code> durch <code>A</code> mit <code>«atpSplitable»</code> markiert ist und beide Klassen <code>Identifiable</code> sind, können Instanzen von <code>C</code> innerhalb eines unteren Teilmodells („Lower partial model“) separat verteilt, instanziiert oder persistiert werden, ohne dass die übergeordnete Identität oder Eindeutigkeit der Aggregationshierarchie gebrochen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwicklungs- und werkzeugrelevante Vorgabe für AUTOSAR-Authoring- und Modellaustauschwerkzeuge:</p>\n<ul class=\"fig-list\"><li>Wenn eine Kompositionsbeziehung zwischen <code>Identifiable</code>-Elementen mit <code>«atpSplitable»</code> versehen ist, müssen Werkzeuge bei der Modellverarbeitung (Diffing, Merging, Export von Partial Models) berücksichtigen, dass Elemente vom Typ <code>C</code> in unterschiedlichen ARXML-Dateien bzw. Teilmodellen vorliegen können.\n</li><li>Für die Modifikations- und Konflikterkennung bedeutet dies, dass das Vorhandensein oder Fehlen von Elementen des Typs <code>C</code> in einem Teilmodell nicht zwingend als Löschung im Gesamtmodell interpretiert werden darf, sondern als splitbare Aggregation gemäß den AUTOSAR-Metamodellregeln aufgelöst werden muss.\n</li></ul>"}], "trans": [{"from": "FIG-e4da0f9fa558a2d5", "to": "FIG-bea43565ecfe70ff", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
